fn handle_map_window(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let Some(window) = x11::map_window_id(body) else {
        return Ok(RequestOutcome::Handled);
    };
    let Some((parent, override_redirect, current_map_state)) = state
        .resources
        .window(window)
        .map(|w| (w.parent, w.override_redirect, w.map_state))
    else {
        // Xorg `dix/dispatch.c::ProcMapWindow` does `dixLookupWindow`
        // first and returns BadWindow on lookup failure. xts5 Xlib4
        // probes XMapWindow on a freed xid (badwin()) and expects the
        // protocol error.
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            window.0,
            8,
        );
    };

    // Per X11 protocol (Xorg `dix/window.c:2661`): "If the window is
    // already mapped, this request has no effect." This MUST guard
    // the MapRequest dispatch below, not just the local mapping —
    // otherwise (a) the root window, which is permanently
    // `Viewable` and whose `parent` field points to itself, fans a
    // phantom MapRequest(parent=root, window=root) to any WM with
    // SubstructureRedirect on root (mate-screensaver hits this on
    // activation; marco's panic-response drops its substructure
    // subscription and breaks compositing of every subsequent
    // top-level); and (b) brisk-menu's ~50 Hz
    // `gtk_window_present`/`XMapRaised` loop on its already-viewable
    // popup re-fans MapNotify → Expose → full-extent damage,
    // triggering marco's per-MapNotify `COMPOSITE::NameWindowPixmap`
    // + recomposite (visible as menu flicker on KMS).
    if current_map_state != MapState::Unmapped {
        debug!(
            "client {} #{} MapWindow 0x{:x} (already mapped — no-op)",
            client_id.0, sequence.0, window.0
        );
        return Ok(RequestOutcome::Handled);
    }

    // SubstructureRedirect on the parent: forward MapRequest to the
    // first subscriber that isn't the requester (the WM), and skip
    // mapping locally.
    let redirect_targets: Vec<ClientId> = if !override_redirect {
        let requester_has = state
            .clients
            .get(&client_id.0)
            .and_then(|c| c.event_masks.get(&parent).copied())
            .is_some_and(|m| m & 0x0010_0000 != 0);
        if requester_has {
            Vec::new()
        } else {
            subscribers_by_id(state, parent, 0x0010_0000)
        }
    } else {
        Vec::new()
    };

    if !redirect_targets.is_empty() {
        debug!(
            "client {} MapWindow 0x{:x} -> MapRequest to WM",
            client_id.0, window.0
        );
        let _dropped = fanout_event_to_clients(state, &redirect_targets, |buf, seq, order| {
            x11::encode_map_request_event(buf, seq, order, parent, window);
        });
        return Ok(RequestOutcome::Handled);
    }

    let transition = state.resources.map_window(window);
    debug_assert!(
        transition.mapping_changed,
        "current_map_state == Unmapped guard above was checked; \
         map_window should now transition",
    );
    let host_xid = state.resources.window(window).and_then(|w| w.host_xid);
    let map_info = state
        .resources
        .window(window)
        .map(|w| (w.parent, w.override_redirect));
    if let Some(xid) = host_xid {
        let _ = backend.map_subwindow(origin, xid.as_raw());
    }
    realize_storage_for_delta(state, backend, origin, &transition.delta);
    // Every window that became viewable under a redirect (its own, or its
    // parent's RedirectSubwindows) gets a backing, as Xorg allocates on
    // realize (`compwindow.c:274`). AFTER `map_subwindow` per the plan's
    // codex-round-6 ordering fix — `map_subwindow` blindly flips
    // `scene_participating = true`, so the Manual participation flip
    // inside `activate_redirect_backing_for` must land last.
    apply_viewability_delta_to_redirects(state, backend, origin, &transition.delta);
    if host_xid.is_some() {
        reapply_redirect_mode_after_map(state, backend, origin, window);
    }

    if let Some((parent, override_redir)) = map_info {
        let _dropped = emit_window_event_to_state(state, window, 0x0002_0000, |buf, seq, order| {
            x11::encode_map_notify_event(buf, seq, order, window, window, override_redir);
        });
        let _dropped = emit_window_event_to_state(state, parent, 0x0008_0000, |buf, seq, order| {
            x11::encode_map_notify_event(buf, seq, order, parent, window, override_redir);
        });
        // Emit VisibilityNotify(Unobscured) then Expose on the window
        // itself when it becomes viewable. Subscribed clients want the
        // newly-viewable window to redraw.
        let viewable = state
            .resources
            .window(window)
            .is_some_and(|w| w.map_state == crate::resources::MapState::Viewable);
        if viewable {
            // VisibilityNotify(Unobscured) for clients selecting
            // VisibilityChangeMask (0x10000). Under yserver's compositor
            // model every viewable top-level is effectively unobscured.
            // Without this, GTK3 leaves the window in a non-paintable
            // visibility state and suppresses all frame-clock paints
            // after the first expose-driven frame — the
            // cinnamon-settings "title changes but content never
            // repaints" freeze. Xorg sends Unobscured on map; we mirror
            // that. (We never send Obscured: a composited top-level is
            // always paintable, and unmap is signalled by UnmapNotify
            // per spec, not VisibilityNotify.)
            let _dropped =
                emit_window_event_to_state(state, window, 0x0001_0000, |buf, seq, order| {
                    x11::encode_visibility_notify_event(buf, seq, order, window, 0);
                });
            // Descendants that were MapWindow'd while this window was
            // still unmapped were Unviewable; mapping this window
            // transitions them to Viewable. Xorg fires
            // VisibilityNotify(Unobscured) on every such descendant
            // (mate-xorg.xtrace seq 0x0147 shows VisibilityNotify on
            // both the FF main window and its child 0x02400010).
            // yserver previously only notified the directly-mapped
            // window, so GTK3's frame clock for the child never woke
            // and the profile chooser stayed blank — the "empty shadow"
            // FF bug on bee. Order with the Expose subtree walk below
            // doesn't matter; both are subtree-wide and idempotent.
            let _dropped = emit_visibility_unobscured_subtree_to_state(state, window);
            send_map_exposures(state, backend, origin, &[window]);
        }
    }
    // Audit #11: Xorg's `miPaintWindow` fires damage on the window's
    // extent when the window becomes viewable (the server-background
    // fill is itself a paint, and DAMAGE hooks every paint).
    // Compositors that subscribe via `XDamageCreate(window)` rely on
    // that first DamageNotify to read the freshly-mapped window's
    // pixels into their own offscreen.
    //
    // Order matters: this MUST come AFTER the MapNotify emissions
    // above. Marco subscribes to SubstructureNotify on root, registers
    // the window in its compositor tree on receiving MapNotify, and
    // only then accepts DAMAGE-Notify on it as a NameWindowPixmap
    // trigger. Pre-fix (damage emitted before MapNotify) marco saw the
    // damage on a window it didn't yet track and silently dropped it,
    // causing mate-panel-top to render blank until a later resize
    // damage finally landed. See mate.xtrace lines 4938→4940 vs
    // mate-xorg.xtrace lines 5164→5173.
    if host_xid.is_some() {
        let _dropped = accumulate_damage_full_to_state(state, window);
        // The mapped window itself keeps its just-fired notify cycle.
        for promoted in transition
            .delta
            .became_viewable
            .iter()
            .filter(|w| **w != window)
        {
            reset_damage_notify_cycle_for_drawable(state, *promoted);
        }
        accumulate_damage_viewable_descendants_to_state(state, window);
    }
    // Xorg MapWindow ends in WindowsRestructured (`dix/window.c:2695`): the
    // pointer's crossings follow MapNotify and Expose within the request.
    backend.windows_restructured(state);
    debug!(
        "client {} #{} MapWindow 0x{:x} viewable+{}",
        client_id.0,
        sequence.0,
        window.0,
        transition.delta.became_viewable.len()
    );
    Ok(RequestOutcome::Handled)
}

fn accumulate_damage_viewable_descendants_to_state(state: &mut ServerState, root: ResourceId) {
    let children: Vec<ResourceId> = state.resources.children(root).to_vec();
    for child in children {
        let child_window = state.resources.window(child);
        let viewable = child_window.is_some_and(|w| w.map_state == MapState::Viewable);
        if !viewable {
            continue;
        }
        let _dropped = accumulate_damage_full_to_state(state, child);
        accumulate_damage_viewable_descendants_to_state(state, child);
    }
}

fn handle_map_subwindows(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    map_subwindows_with_delta(state, backend, origin, client_id, sequence, body)
        .map(|(outcome, _delta)| outcome)
}

/// MapSubwindows; also returns the union of the children's viewability deltas.
fn map_subwindows_with_delta(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<(RequestOutcome, ViewabilityDelta)> {
    let mut delta = ViewabilityDelta::default();
    let Some(parent) = x11::map_window_id(body) else {
        return Ok((RequestOutcome::Handled, delta));
    };
    if state.resources.window(parent).is_none() {
        // Xorg `dix/dispatch.c::ProcMapSubwindows` returns BadWindow
        // for an unknown parent xid. xts5 Xlib4 probes XMapSubwindows
        // on badwin() and expects the protocol error.
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            parent.0,
            9,
        )
        .map(|outcome| (outcome, delta));
    }
    let children: Vec<ResourceId> = state.resources.children(parent).to_vec();
    let mut newly_viewable = Vec::new();
    for child in children {
        let transition = state.resources.map_window(child);
        let was_unmapped = transition.mapping_changed;
        let host_xid = state.resources.window(child).and_then(|w| w.host_xid);
        let override_redirect = state
            .resources
            .window(child)
            .is_some_and(|w| w.override_redirect);
        if let Some(xid) = host_xid {
            let _ = backend.map_subwindow(origin, xid.as_raw());
        }
        realize_storage_for_delta(state, backend, origin, &transition.delta);
        // Same post-hook as `handle_map_window`: AFTER `map_subwindow`.
        apply_viewability_delta_to_redirects(state, backend, origin, &transition.delta);
        delta.extend(transition.delta);
        if host_xid.is_some() {
            reapply_redirect_mode_after_map(state, backend, origin, child);
            // Audit #11: see `handle_map_window` for the rationale.
            // Mirror the damage bump so MapSubwindows-driven mass
            // maps (mate-panel applet realize cascade, GTK
            // children-on-show) also notify subscribed compositors.
            let _dropped = accumulate_damage_full_to_state(state, child);
        }
        if was_unmapped {
            let _dropped =
                emit_window_event_to_state(state, child, 0x0002_0000, |buf, seq, order| {
                    x11::encode_map_notify_event(buf, seq, order, child, child, override_redirect);
                });
            let _dropped =
                emit_window_event_to_state(state, parent, 0x0008_0000, |buf, seq, order| {
                    x11::encode_map_notify_event(buf, seq, order, parent, child, override_redirect);
                });
        }
        // Only a child now Viewable (its parent mapped too) is exposed,
        // with the descendants that mapping it promoted to Viewable.
        let viewable = state
            .resources
            .window(child)
            .is_some_and(|w| w.map_state == MapState::Viewable);
        if was_unmapped && viewable {
            newly_viewable.push(child);
        }
    }
    // Xorg maps them all, then validates and exposes once: top-most first,
    // each clipped by the siblings mapped with it (`dix/window.c:2760-2775`).
    newly_viewable.reverse();
    send_map_exposures(state, backend, origin, &newly_viewable);
    // Xorg MapSubwindows: one WindowsRestructured after the batch
    // (`dix/window.c:2775`).
    backend.windows_restructured(state);
    debug!(
        "client {} #{} MapSubwindows viewable+{}",
        client_id.0,
        sequence.0,
        delta.became_viewable.len()
    );
    Ok((RequestOutcome::Handled, delta))
}

fn handle_unmap_window(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some(window) = x11::map_window_id(body) {
        if state.resources.window(window).is_none() {
            // Xorg `dix/dispatch.c::ProcUnmapWindow` returns BadWindow
            // via dixLookupWindow before unmapping. xts5 Xlib4 probes
            // XUnmapWindow on badwin() and expects the protocol error.
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_WINDOW,
                window.0,
                10,
            );
        }
        let host_xid = state.resources.window(window).and_then(|w| w.host_xid);
        let viewable_before = state
            .resources
            .window(window)
            .is_some_and(|w| w.map_state == MapState::Viewable);
        let clips_before = if viewable_before {
            crate::core_loop::clip_list::clip_lists_under(state, window)
        } else {
            Vec::new()
        };
        let transition = state.resources.unmap_window(window);
        let was_mapped = transition.mapping_changed;
        let parent = if was_mapped {
            state
                .resources
                .window(window)
                .map_or(ROOT_WINDOW, |w| w.parent)
        } else {
            ROOT_WINDOW
        };
        if let Some(xid) = host_xid {
            let _ = backend.unmap_subwindow(origin, xid.as_raw());
        }
        // Xorg frees each redirect pixmap at unrealize (`compwindow.c:291`).
        apply_viewability_delta_to_redirects(state, backend, origin, &transition.delta);
        release_storage_for_delta(state, backend, origin, &transition.delta);
        // XI1: an active device grab is released automatically when its
        // grab window becomes not viewable (XTS XGrabDeviceKey-9; Xorg
        // DeactivateGrabsOnWindowUnmap shape).
        if was_mapped {
            let released: Vec<u16> = state
                .xi1_active_grabs
                .iter()
                .filter(|(_, g)| {
                    state
                        .resources
                        .window(g.grab_window)
                        .is_none_or(|w| w.map_state != crate::resources::MapState::Viewable)
                })
                .map(|(d, _)| *d)
                .collect();
            for dev in released {
                state.xi1_active_grabs.remove(&dev);
                let xid_map = backend.xid_map().clone();
                crate::core_loop::pointer_fanout::xi1_thaw_device(state, backend, &xid_map, dev);
            }
        }
        if was_mapped {
            let _dropped =
                emit_window_event_to_state(state, window, 0x0002_0000, |buf, seq, order| {
                    x11::encode_unmap_notify_event(buf, seq, order, window, window, false);
                });
            let _dropped =
                emit_window_event_to_state(state, parent, 0x0008_0000, |buf, seq, order| {
                    x11::encode_unmap_notify_event(buf, seq, order, parent, window, false);
                });
            // What it covered is exposed: its parent's and lower
            // siblings' backgrounds painted there, and Expose sent
            // (`UnmapWindow`, `dix/window.c:2856-2866`).
            if viewable_before {
                let after = crate::core_loop::clip_list::clip_lists_under(state, window);
                for (w, region) in
                    crate::core_loop::clip_list::newly_exposed(&clips_before, after, None)
                {
                    send_window_exposures(state, backend, origin, w, &region, true);
                }
            }
            // XI1: a device focus on a window that just became
            // unviewable reverts per its revert_to, emitting
            // DeviceFocusIn/Out (Xi/exevents.c
            // DeleteDeviceFromAnyExtEvents). After UnmapNotify, matching
            // Xorg's UnmapWindow → UnrealizeTree ordering.
            crate::core_loop::xi1_focus::revert_unviewable_focus(state);
            // Core focus likewise (Xorg UnrealizeTree →
            // DeleteWindowFromAnyEvents): covers the focus window
            // itself or any unmapped ancestor.
            revert_core_focus_if_unviewable(state);
            // Active grabs on a window that just became unviewable
            // deactivate too (same Xorg path).
            release_core_grabs_for_unviewable(state, backend);
            // Then WindowsRestructured (`dix/window.c:2871`).
            backend.windows_restructured(state);
        }
    }
    debug!("client {} #{} UnmapWindow", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_unmap_subwindows(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    unmap_subwindows_with_delta(state, backend, origin, client_id, sequence, body)
        .map(|(outcome, _delta)| outcome)
}

/// UnmapSubwindows; also returns the union of the children's viewability deltas.
fn unmap_subwindows_with_delta(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<(RequestOutcome, ViewabilityDelta)> {
    let mut delta = ViewabilityDelta::default();
    let Some(parent) = x11::map_window_id(body) else {
        return Ok((RequestOutcome::Handled, delta));
    };
    struct PendingUnmap {
        child: ResourceId,
        host_xid: Option<crate::backend::WindowHandle>,
    }
    let Some(mut children) = state.resources.mapped_children_bottom_to_top(parent) else {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            parent.0,
            11,
        )
        .map(|outcome| (outcome, delta));
    };
    // UnmapSubwindows stops at RealChildHead too (dix/window.c:2897): the
    // overlay window stays mapped.
    if parent == ROOT_WINDOW {
        children.retain(|child| *child != COMPOSITE_OVERLAY_WINDOW);
    }
    let clip_before = crate::core_loop::clip_list::clip_list(state, parent);
    // Snapshot mapping order + collect host xids; unmap each in the
    // resource table.
    let mut pending: Vec<PendingUnmap> = Vec::new();
    for child in children {
        let host_xid = state.resources.window(child).and_then(|w| w.host_xid);
        let transition = state.resources.unmap_window(child);
        delta.extend(transition.delta);
        if transition.mapping_changed {
            pending.push(PendingUnmap { child, host_xid });
        }
    }
    for item in pending {
        if let Some(xid) = item.host_xid {
            let _ = backend.unmap_subwindow(origin, xid.as_raw());
        }
        let child = item.child;
        let _dropped = emit_window_event_to_state(state, child, 0x0002_0000, |buf, seq, order| {
            x11::encode_unmap_notify_event(buf, seq, order, child, child, false);
        });
        let _dropped = emit_window_event_to_state(state, parent, 0x0008_0000, |buf, seq, order| {
            x11::encode_unmap_notify_event(buf, seq, order, parent, child, false);
        });
    }
    // Xorg frees each redirect pixmap at unrealize (`compwindow.c:291`).
    apply_viewability_delta_to_redirects(state, backend, origin, &delta);
    release_storage_for_delta(state, backend, origin, &delta);
    // The parent is exposed where its children were (`dix/window.c:2925-2933`).
    let gained = crate::core_loop::clip_list::subtract(
        &crate::core_loop::clip_list::clip_list(state, parent),
        &clip_before,
    );
    send_window_exposures(state, backend, origin, parent, &gained, true);
    crate::core_loop::xi1_focus::revert_unviewable_focus(state);
    revert_core_focus_if_unviewable(state);
    release_core_grabs_for_unviewable(state, backend);
    // Xorg UnmapSubwindows: one WindowsRestructured (`dix/window.c:2939`).
    backend.windows_restructured(state);
    debug!(
        "client {} #{} UnmapSubwindows viewable-{}",
        client_id.0,
        sequence.0,
        delta.became_unviewable.len()
    );
    Ok((RequestOutcome::Handled, delta))
}

fn handle_ge_request(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
) -> io::Result<RequestOutcome> {
    if header.data == 0 {
        debug!("client {} #{} GEQueryVersion", client_id.0, sequence.0);
        let Some(client) = state.clients.get_mut(&client_id.0) else {
            return Ok(RequestOutcome::Handled);
        };
        let byte_order = client.byte_order;
        let mut buf: Vec<u8> = Vec::with_capacity(32);
        x11::write_ge_query_version_reply(&mut buf, byte_order, sequence)?;
        return Ok(write_to_client(client, client_id, &buf));
    }
    emit_x11_error_with_minor(
        state,
        client_id,
        sequence,
        x11::error::BAD_REQUEST,
        0,
        u16::from(header.data),
        header.opcode,
    )
}

fn handle_big_requests_request(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
) -> io::Result<RequestOutcome> {
    if header.data != 0 {
        // Malformed minor — the reader thread parked waiting for an
        // Apply / Ignore signal after sending the Enable through the
        // channel; unblock it with `IgnoreBigRequests` so it doesn't
        // deadlock.
        if let Some(client) = state.clients.get(&client_id.0)
            && let Some(tx) = client.reader_control.as_ref()
        {
            let _ = tx.send(crate::server::ReaderControl::IgnoreBigRequests);
        }
        return emit_x11_error_with_minor(
            state,
            client_id,
            sequence,
            x11::error::BAD_REQUEST,
            0,
            u16::from(header.data),
            header.opcode,
        );
    }
    debug!("client {} #{} BigRequestsEnable", client_id.0, sequence.0);
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    client.big_requests_enabled = true;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_big_requests_enable_reply(
        &mut buf,
        byte_order,
        sequence,
        x11::MAX_BIG_REQUEST_UNITS,
    )?;
    let outcome = write_to_client(client, client_id, &buf);
    // Unblock the reader so subsequent requests use big-framing.
    if let Some(tx) = client.reader_control.as_ref() {
        let _ = tx.send(crate::server::ReaderControl::ApplyBigRequests);
    }
    Ok(outcome)
}

/// Check the variable arrays that Xorg validates with `REQUEST_FIXED_SIZE`
/// or by walking XISelectEvents records. All typed count fields have been
/// swapped to little-endian by the reader before this production entry point.
fn xi2_request_has_complete_dynamic_tail(minor: u8, body: &[u8]) -> bool {
    fn u16_at(body: &[u8], offset: usize) -> Option<usize> {
        let bytes = body.get(offset..offset.checked_add(2)?)?;
        Some(usize::from(u16::from_le_bytes([bytes[0], bytes[1]])))
    }

    fn words_fit(body: &[u8], start: usize, words: usize) -> Option<usize> {
        let bytes = words.checked_mul(4)?;
        let end = start.checked_add(bytes)?;
        (end <= body.len()).then_some(end)
    }

    match minor {
        // SProcXISelectEvents checks each xXIEventMask header and mask_len
        // region, returning BadLength before ProcXISelectEvents mutates masks.
        46 => {
            let Some(num_masks) = u16_at(body, 4) else {
                return false;
            };
            let mut pos = 8usize;
            for _ in 0..num_masks {
                let Some(device_and_len_end) = pos.checked_add(4) else {
                    return false;
                };
                if device_and_len_end > body.len() {
                    return false;
                }
                let Some(mask_words) = u16_at(body, pos + 2) else {
                    return false;
                };
                let Some(mask_end) = words_fit(body, device_and_len_end, mask_words) else {
                    return false;
                };
                pos = mask_end;
            }
            true
        }
        // ProcXIGrabDevice checks mask_len words after its 20-byte body
        // prefix. Those words are byte masks and remain unswapped.
        51 => {
            let Some(mask_len) = u16_at(body, 18) else {
                return false;
            };
            words_fit(body, 20, mask_len).is_some()
        }
        // SProcXIPassiveGrabDevice checks the mask and modifier spans together
        // before its modifier CARD32 swap loop.
        54 => {
            let (Some(num_modifiers), Some(mask_len)) = (u16_at(body, 18), u16_at(body, 20)) else {
                return false;
            };
            let Some(mask_end) = words_fit(body, 28, mask_len) else {
                return false;
            };
            words_fit(body, mask_end, num_modifiers).is_some()
        }
        // SProcXIPassiveUngrabDevice checks num_modifiers CARD32s after its
        // 16-byte fixed body.
        55 => {
            let Some(num_modifiers) = u16_at(body, 10) else {
                return false;
            };
            words_fit(body, 16, num_modifiers).is_some()
        }
        _ => true,
    }
}

fn handle_get_window_attributes(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let id = x11::drawable_request_id(body).unwrap_or(ROOT_WINDOW);
    debug!(
        "client {} #{} GetWindowAttributes 0x{:x}",
        client_id.0, sequence.0, id.0,
    );
    // Spec: BadWindow on unknown window ID. Don't silently fall back to
    // ROOT_WINDOW — xts probes stale/destroyed XIDs and expects the
    // protocol error.
    if state.resources.window(id).is_none() {
        return emit_x11_error(state, client_id, sequence, x11::error::BAD_WINDOW, id.0, 3);
    }
    let target = id;
    let your_event_mask = state
        .clients
        .get(&client_id.0)
        .and_then(|c| c.event_masks.get(&target).copied())
        .unwrap_or(0);
    let all_event_masks: u32 = state
        .clients
        .values()
        .filter_map(|c| c.event_masks.get(&target).copied())
        .fold(0u32, |a, b| a | b);
    let attrs = window_attributes(
        state.resources.window(target),
        all_event_masks,
        your_event_mask,
    );
    if let Some(window) = state.resources.window(target) {
        debug!(
            "client {} #{} GetWindowAttributes reply 0x{:x}: parent=0x{:x} map_state={} override_redirect={}",
            client_id.0,
            sequence.0,
            target.0,
            window.parent.0,
            attrs.map_state,
            attrs.override_redirect,
        );
    }
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(48);
    x11::write_get_window_attributes_reply(&mut buf, byte_order, sequence, attrs)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn window_attributes(
    window: Option<&Window>,
    all_event_masks: u32,
    your_event_mask: u32,
) -> x11::WindowAttributes {
    let window = window.expect("root window exists");
    x11::WindowAttributes {
        visual: window.visual,
        class: window.class.protocol_value(),
        bit_gravity: window.bit_gravity,
        win_gravity: window.win_gravity,
        backing_store: window.backing_store,
        backing_planes: window.backing_planes,
        backing_pixel: window.backing_pixel,
        save_under: window.save_under,
        map_is_installed: true,
        map_state: window.map_state.protocol_value(),
        override_redirect: window.override_redirect,
        colormap: window.colormap,
        all_event_masks,
        your_event_mask,
        do_not_propagate_mask: window.do_not_propagate_mask,
    }
}

fn handle_circulate_window(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() < 4 {
        debug!(
            "client {} #{} CirculateWindow (short body)",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    }
    let container = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
    let direction = header.data;
    if state.resources.window(container).is_none() {
        // Xorg `dix/dispatch.c::ProcCirculateWindow` returns BadWindow
        // via dixLookupWindow on an unknown xid. xts5 Xlib4 probes
        // XCirculateSubwindows{,Up,Down} on badwin() and expects it.
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_WINDOW,
            container.0,
            13,
        );
    }
    let Some(child) = state.circulate_candidate(container, direction) else {
        return Ok(RequestOutcome::Handled);
    };
    // SubstructureRedirect on the container by another client turns it into
    // a CirculateRequest (Xorg MaybeDeliverEventsToClient skips the
    // requester).
    let redirect_target = subscribers_by_id(state, container, 0x0010_0000)
        .into_iter()
        .find(|c| *c != client_id);
    if let Some(target) = redirect_target {
        let _dropped = fanout_event_to_clients(state, &[target], |buf, seq, order| {
            let _ =
                x11::write_circulate_request_event(buf, order, seq, container, child, direction);
        });
    } else {
        let tree_change = crate::core_loop::clip_list::TreeChange::begin(state, child, None);
        state.resources.circulate_child(child, direction == 0);
        if let Some(xid) = state.resources.window(child).and_then(|w| w.host_xid) {
            let _ = backend.configure_subwindow(
                None,
                xid.as_raw(),
                crate::host_x11::HostSubwindowConfig {
                    x: None,
                    y: None,
                    width: None,
                    height: None,
                    border_width: None,
                    sibling: None,
                    stack_mode: Some(if direction == 0 { 0 } else { 1 }),
                },
            );
        }
        backend.sync_top_level_order(state);
        // CirculateNotify to the window's StructureNotify and the parent's
        // SubstructureNotify selectors, each with its own event window; the
        // place (OnTop 0 / OnBottom 1) equals the direction.
        let _dropped = emit_window_event_to_state(state, child, 0x0002_0000, |buf, seq, order| {
            let _ = x11::write_circulate_notify_event(buf, order, seq, child, child, direction);
        });
        let _dropped =
            emit_window_event_to_state(state, container, 0x0008_0000, |buf, seq, order| {
                let _ =
                    x11::write_circulate_notify_event(buf, order, seq, container, child, direction);
            });
        // Then ReflectStackChange validates and exposes (`dix/window.c:2149-2176`).
        if let Some(change) = tree_change {
            for (w, region) in change.exposed(state, None) {
                send_window_exposures(state, backend, None, w, &region, true);
            }
        }
        // Xorg ReflectStackChange (`dix/window.c:2179`).
        backend.windows_restructured(state);
    }
    debug!("client {} #{} CirculateWindow", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_create_cursor(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 28 {
        let cursor_id = ResourceId(u32::from_le_bytes([body[0], body[1], body[2], body[3]]));
        if state.resources.xid_in_use(cursor_id)
            || xid_out_of_client_range(state, client_id, cursor_id.0)
        {
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_ID_CHOICE,
                cursor_id.0,
                93,
            );
        }
        let source_id = ResourceId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
        let mask_id = ResourceId(u32::from_le_bytes([body[8], body[9], body[10], body[11]]));
        let fore = (
            u16::from_le_bytes([body[12], body[13]]),
            u16::from_le_bytes([body[14], body[15]]),
            u16::from_le_bytes([body[16], body[17]]),
        );
        let back = (
            u16::from_le_bytes([body[18], body[19]]),
            u16::from_le_bytes([body[20], body[21]]),
            u16::from_le_bytes([body[22], body[23]]),
        );
        let hot_x = u16::from_le_bytes([body[24], body[25]]);
        let hot_y = u16::from_le_bytes([body[26], body[27]]);

        let src_host = state.resources.pixmap(source_id).and_then(|p| p.host_xid);
        let mask_host = if mask_id.0 == 0 {
            None
        } else {
            state.resources.pixmap(mask_id).and_then(|p| p.host_xid)
        };
        state.resources.create_cursor(client_id, cursor_id);
        if let Some(src_host) = src_host {
            match backend.create_cursor(origin, src_host, mask_host, fore, back, hot_x, hot_y) {
                Ok(handle) => {
                    state.resources.set_cursor_host_xid(cursor_id, handle);
                }
                Err(err) => {
                    log::warn!("client {} CreateCursor failed: {err}", client_id.0);
                }
            }
        }
    }
    debug!("client {} #{} CreateCursor", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_create_glyph_cursor(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if body.len() >= 28
        && let Some(cursor) = x11::create_glyph_cursor_id(body)
    {
        let new_id = cursor.0;
        let validation_failed = {
            let handle = state.clients.get(&client_id.0).expect("client registered");
            let owned = crate::server::IdAllocator::validate_owned(
                new_id,
                handle.resource_id_base,
                handle.resource_id_mask,
            );
            let in_use = state.xid_occupied(cursor.0);
            !owned || in_use
        };
        if validation_failed {
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_ID_CHOICE,
                new_id,
                94,
            );
        }

        let source_id = ResourceId(u32::from_le_bytes([body[4], body[5], body[6], body[7]]));
        let mask_id = ResourceId(u32::from_le_bytes([body[8], body[9], body[10], body[11]]));
        let source_char = u16::from_le_bytes([body[12], body[13]]);
        let mask_char = u16::from_le_bytes([body[14], body[15]]);
        let fore = (
            u16::from_le_bytes([body[16], body[17]]),
            u16::from_le_bytes([body[18], body[19]]),
            u16::from_le_bytes([body[20], body[21]]),
        );
        let back = (
            u16::from_le_bytes([body[22], body[23]]),
            u16::from_le_bytes([body[24], body[25]]),
            u16::from_le_bytes([body[26], body[27]]),
        );

        let src_host = state.resources.font(source_id).map(|f| f.host_xid);
        let mask_host = if mask_id.0 == 0 {
            None
        } else {
            state.resources.font(mask_id).map(|f| f.host_xid)
        };

        state.resources.create_glyph_cursor(client_id, cursor);
        if let Some(src_host) = src_host {
            match backend.create_glyph_cursor(
                origin,
                src_host,
                mask_host,
                source_char,
                mask_char,
                fore,
                back,
            ) {
                Ok(handle) => {
                    state.resources.set_cursor_host_xid(cursor, handle);
                }
                Err(err) => {
                    log::warn!("client {} CreateGlyphCursor failed: {err}", client_id.0);
                }
            }
        } else {
            log::warn!(
                "client {} CreateGlyphCursor: source font 0x{:x} unknown",
                client_id.0,
                source_id.0
            );
        }
    }
    debug!("client {} #{} CreateGlyphCursor", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

fn handle_query_extension(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    let name = x11::query_extension_name(body);
    let (present, major_opcode, first_event, first_error) = extension_query_reply(&name, backend)
        .map(|(major_opcode, first_event, first_error)| {
            (true, major_opcode, first_event, first_error)
        })
        .unwrap_or((false, 0, 0, 0));
    debug!(
        "client {} #{} QueryExtension {:?} -> {}",
        client_id.0,
        sequence.0,
        name,
        if present { "present" } else { "absent" }
    );
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32);
    x11::write_query_extension_reply(
        &mut buf,
        byte_order,
        sequence,
        present,
        major_opcode,
        first_event,
        first_error,
    )?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_list_extensions(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
) -> io::Result<RequestOutcome> {
    debug!("client {} #{} ListExtensions", client_id.0, sequence.0);
    let names = advertised_extension_names(backend);
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let byte_order = client.byte_order;
    let mut buf: Vec<u8> = Vec::with_capacity(32 + names.len() * 16);
    x11::write_list_extensions_reply(&mut buf, byte_order, sequence, &names)?;
    Ok(write_to_client(client, client_id, &buf))
}

fn handle_allow_events(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    // Core AllowEvents modes (X11 spec):
    //   0 AsyncPointer  1 SyncPointer   2 ReplayPointer
    //   3 AsyncKeyboard 4 SyncKeyboard  5 ReplayKeyboard
    //   6 AsyncBoth     7 SyncBoth
    let mode = header.data;
    if mode > 7 {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_VALUE,
            u32::from(mode),
            35,
        );
    }
    let time = body
        .get(0..4)
        .map_or(0, |b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]));
    apply_allow_events(state, backend, client_id, sequence, mode, time)
}

/// Map an XI2 `XIAllowEvents` mode + registry-classified target onto the
/// equivalent core `AllowSome` mode consumed by [`apply_allow_events`]. The
/// paired modes act on the OTHER device. Touch modes (`XIAcceptTouch`=6 /
/// `XIRejectTouch`=7) and anything unknown are unsupported → `None` (no-op).
/// XI2 mode constants per `X11/extensions/XI2.h`: AsyncDevice=0,
/// SyncDevice=1, ReplayDevice=2, AsyncPairedDevice=3, AsyncPair=4,
/// SyncPair=5.
fn xi2_allow_mode_to_core(xi2_mode: u8, kbd: bool) -> Option<u8> {
    // Core modes: 0 AsyncPointer 1 SyncPointer 2 ReplayPointer
    //             3 AsyncKeyboard 4 SyncKeyboard 5 ReplayKeyboard
    //             6 AsyncBoth 7 SyncBoth
    Some(match xi2_mode {
        0 => u8::from(kbd) * 3,     // XIAsyncDevice  → Async{Pointer,Keyboard}
        1 => 1 + u8::from(kbd) * 3, // XISyncDevice   → Sync{Pointer,Keyboard}
        2 => 2 + u8::from(kbd) * 3, // XIReplayDevice → Replay{Pointer,Keyboard}
        3 => u8::from(!kbd) * 3,    // XIAsyncPairedDevice → async the PAIRED device
        4 => 6,                     // XIAsyncPair → AsyncBoth
        5 => 7,                     // XISyncPair  → SyncBoth
        _ => return None,           // XIAcceptTouch / XIRejectTouch / unknown
    })
}

/// XI2 AllowEvents for a slave device uses the exact device's freeze state;
/// paired modes use the opposite master returned by the registry attachment.
fn apply_xi2_allow_events_for_slave(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
    device_id: u16,
    is_keyboard: bool,
    xi_mode: u8,
    time: u32,
) -> io::Result<RequestOutcome> {
    use crate::server::Xi1SyncState;

    if xi_mode > 5 {
        return Ok(RequestOutcome::Handled);
    }
    let paired_id = crate::core_loop::pointer_fanout::xi1_other_input_device(state, device_id);
    let target_id = if xi_mode == 3 {
        let Some(paired_id) = paired_id else {
            return Ok(RequestOutcome::Handled);
        };
        paired_id
    } else {
        device_id
    };
    let target_owner = crate::core_loop::pointer_fanout::xi1_device_grab_owner(state, target_id);
    let target_state = state
        .xi1_frozen
        .get(&target_id)
        .map_or(Xi1SyncState::Thawed, |freeze| freeze.state);
    let target_other = state
        .xi1_frozen
        .get(&target_id)
        .and_then(|freeze| freeze.other);
    let is_frozen_by_client = target_owner == Some(client_id)
        && target_state >= Xi1SyncState::FrozenNoEvent
        || target_other == Some(client_id);
    if !is_frozen_by_client {
        return Ok(RequestOutcome::Handled);
    }
    let now = state
        .timestamp_now()
        .max(state.xi1_last_input_time)
        .max(if is_keyboard {
            state.last_keyboard_grab_time
        } else {
            state.last_pointer_grab_time
        });
    if time != 0 && crate::core_loop::xi1_focus::time_after(time, now) {
        return Ok(RequestOutcome::Handled);
    }

    let mut devices = Vec::with_capacity(2);
    match xi_mode {
        0..=2 => devices.push(device_id),
        3 => devices.push(target_id),
        4 | 5 => {
            devices.push(device_id);
            if let Some(paired_id) = paired_id {
                devices.push(paired_id);
            }
        }
        _ => return Ok(RequestOutcome::Handled),
    }
    let new_state = match xi_mode {
        0 | 3 | 4 => Some(Xi1SyncState::Thawed),
        1 | 5 => Some(Xi1SyncState::FreezeNextEvent),
        2 => Some(Xi1SyncState::Thawed),
        _ => None,
    };
    for id in &devices {
        if let Some(new_state) = new_state {
            let freeze = state.xi1_frozen.entry(*id).or_default();
            freeze.state = new_state;
            if freeze.other == Some(client_id) {
                freeze.other = None;
            }
            if matches!(xi_mode, 0 | 3 | 4) {
                freeze.stored = None;
            }
        }
    }

    if xi_mode == 2 {
        let stored = state
            .xi1_frozen
            .get_mut(&device_id)
            .and_then(|freeze| freeze.stored.take());
        if let Some(crate::server::QueuedInputEvent::HostPointer(_)) = stored {
            if let Some(grab) = state.xi2_pointer_grabs.get(&device_id)
                && grab.owner == client_id
            {
                state.xi2_pointer_grabs.remove(&device_id);
                state.reattach_xi2_slave(device_id);
            }
            if let Some(crate::server::QueuedInputEvent::HostPointer(event)) = stored {
                let xid_map = backend.xid_map().clone();
                let _dropped =
                    crate::core_loop::pointer_fanout::replay_frozen_pointer_event_to_state(
                        state, backend, &xid_map, event,
                    );
            }
        } else if let Some(crate::server::QueuedInputEvent::HostKeyTransition(
            event,
            master_transition_accepted,
        )) = stored
        {
            if state
                .xi2_keyboard_grabs
                .get(&device_id)
                .is_some_and(|grab| grab.owner == client_id)
            {
                state.xi2_keyboard_grabs.remove(&device_id);
                state.reattach_xi2_slave(device_id);
            }
            let _dropped =
                crate::core_loop::key_fanout::replay_frozen_key_to_focus_after_transition(
                    state,
                    event,
                    master_transition_accepted,
                );
        } else if let Some(crate::server::QueuedInputEvent::HostKey(event)) = stored {
            if state
                .xi2_keyboard_grabs
                .get(&device_id)
                .is_some_and(|grab| grab.owner == client_id)
            {
                state.xi2_keyboard_grabs.remove(&device_id);
                state.reattach_xi2_slave(device_id);
            }
            let _dropped = crate::core_loop::key_fanout::replay_frozen_key_to_focus(state, event);
        }
    }
    let xid_map = backend.xid_map().clone();
    crate::core_loop::pointer_fanout::xi1_compute_freezes(state, backend, &xid_map);
    debug!(
        "client {} #{} XIAllowEvents slave device={} mode={}",
        client_id.0, sequence.0, device_id, xi_mode
    );
    Ok(RequestOutcome::Handled)
}

/// Shared `AllowSome` implementation (Xorg `dix/events.c:1823`), driven by
/// BOTH core `AllowEvents` (mode straight from the request) AND XI2
/// `XIAllowEvents` (mode mapped from the XI2 mode + deviceid; see
/// [`xi2_allow_mode_to_core`]). Routing the XI2 path through here — rather
/// than the old partial reimplementation in the XI2 handler — kills a
/// recurring class of divergence bugs where the XI2 copy mishandled modes
/// the core path got right (the desktop rubber-band = Async/Replay thaw
/// gap; the Cinnamon input freeze = `XISyncDevice`/mode-1 treated as a
/// no-op). `mode` is a CORE AllowEvents mode (0..=7); `time` is the
/// request timestamp.
fn apply_allow_events(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    client_id: ClientId,
    sequence: SequenceNumber,
    mode: u8,
    time: u32,
) -> io::Result<RequestOutcome> {
    // Xorg AllowSome: the request is a no-op when its time is LATER
    // than the current time or EARLIER than the client's grab time
    // (XAllowEvents-12/13). Pointer modes gate on the pointer's grab
    // time, keyboard and *Both modes on the keyboard's.
    let grab_time = if matches!(mode, 0..=2) {
        state.last_pointer_grab_time
    } else {
        state.last_keyboard_grab_time
    };
    let now = state
        .timestamp_now()
        .max(state.xi1_last_input_time)
        .max(grab_time);
    if time != 0
        && (crate::core_loop::xi1_focus::time_after(time, now)
            || crate::core_loop::xi1_focus::time_after(grab_time, time))
    {
        debug!(
            "client {} #{} AllowEvents ignored (time {time} outside [{grab_time}, {now}])",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    }
    debug!(
        "client {} #{} AllowEvents mode={} frozen_pointer={} frozen_keyboard={}",
        client_id.0,
        sequence.0,
        mode,
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_POINTER)
            .is_some_and(|f| f.stored.is_some()),
        state
            .xi1_frozen
            .get(&crate::xinput::DEVICEID_MASTER_KEYBOARD)
            .is_some_and(|f| f.stored.is_some()),
    );

    // Port of Xorg AllowSome (dix/events.c:1823). `thisDev` is the
    // pointer for the pointer modes and the keyboard for the keyboard
    // and *Both modes; the request is a no-op unless this client's
    // grab holds the device frozen, or the device is synced on this
    // client's behalf.
    use crate::server::Xi1SyncState;
    let dev_this = if matches!(mode, 0..=2) {
        crate::xinput::DEVICEID_MASTER_POINTER
    } else {
        crate::xinput::DEVICEID_MASTER_KEYBOARD
    };
    let grab_owner_of = |state: &ServerState, dev: u16| -> Option<ClientId> {
        crate::core_loop::pointer_fanout::xi1_device_grab_owner(state, dev)
    };
    let this_grabbed = grab_owner_of(state, dev_this) == Some(client_id);
    let this_state = state
        .xi1_frozen
        .get(&dev_this)
        .map_or(Xi1SyncState::Thawed, |f| f.state);
    let this_synced = state.xi1_frozen.get(&dev_this).and_then(|f| f.other) == Some(client_id);
    if !((this_grabbed && this_state >= Xi1SyncState::FrozenNoEvent) || this_synced) {
        debug!(
            "client {} #{} AllowEvents no-op (not frozen by this client: grabbed={this_grabbed} state={this_state:?} synced={this_synced})",
            client_id.0, sequence.0
        );
        return Ok(RequestOutcome::Handled);
    }

    let pointer_replay = mode == 2;
    let keyboard_replay = mode == 5;

    // State transitions per mode (Xorg AllowSome switch). The queued
    // events play AFTER the transition so the freeze gate at fanout
    // entry sees the new state: Async → events flow; Sync →
    // FreezeNextEvent lets them flow until the next key/button trips
    // the re-freeze (FreezeThisEventIfNeededForSyncGrab).
    let set_state = |state: &mut ServerState, dev: u16, st: Xi1SyncState| {
        let f = state.xi1_frozen.entry(dev).or_default();
        f.state = st;
        if f.other == Some(client_id) {
            f.other = None;
        }
    };
    let dev_ptr = crate::xinput::DEVICEID_MASTER_POINTER;
    let dev_kbd = crate::xinput::DEVICEID_MASTER_KEYBOARD;
    // Xorg AllowSome `othersFrozen`: the *Both modes (AsyncBoth /
    // SyncBoth) only act when ANOTHER device this client grabbed is
    // itself frozen (dix/events.c:1872, 1886 — `if (othersFrozen)`).
    // Without this gate a client could thaw/re-freeze its own device
    // via *Both even when no paired device is frozen, leaving later
    // grabs in the wrong sync state. In the two-device model "others"
    // relative to dev_this (keyboard, for *Both) is the pointer.
    let others_frozen = {
        let other = if dev_this == dev_kbd {
            dev_ptr
        } else {
            dev_kbd
        };
        grab_owner_of(state, other) == Some(client_id)
            && state
                .xi1_frozen
                .get(&other)
                .is_some_and(|f| f.state >= Xi1SyncState::FrozenNoEvent)
    };
    match mode {
        0 | 2 => set_state(state, dev_ptr, Xi1SyncState::Thawed),
        1 => set_state(state, dev_ptr, Xi1SyncState::FreezeNextEvent),
        3 | 5 => set_state(state, dev_kbd, Xi1SyncState::Thawed),
        4 => set_state(state, dev_kbd, Xi1SyncState::FreezeNextEvent),
        6 if others_frozen => {
            // AsyncBoth thaws every device this client's grabs froze.
            for dev in [dev_ptr, dev_kbd] {
                if grab_owner_of(state, dev) == Some(client_id)
                    || state.xi1_frozen.get(&dev).and_then(|f| f.other) == Some(client_id)
                {
                    set_state(state, dev, Xi1SyncState::Thawed);
                }
            }
        }
        7 if others_frozen => {
            // SyncBoth arms FreezeBothNextEvent on the client's
            // grabbed devices.
            for dev in [dev_ptr, dev_kbd] {
                if grab_owner_of(state, dev) == Some(client_id)
                    || state.xi1_frozen.get(&dev).and_then(|f| f.other) == Some(client_id)
                {
                    set_state(state, dev, Xi1SyncState::FreezeBothNextEvent);
                }
            }
        }
        // *Both with no paired device frozen → no-op (Xorg).
        6 | 7 => {}
        _ => {}
    }

    // Withheld pointer events. The activating press of a sync passive
    // grab was already delivered to the grab owner — only Replay
    // re-delivers it (to the natural target, grab bypassed); the
    // async/sync releases just drop it. The QUEUE (events that arrived
    // during the freeze, delivered to nobody) plays through the normal
    // pipeline on every pointer-side release — Xorg
    // PlayReleasedEvents; with the grab still active they route to
    // the grab owner.
    let pointer_side = matches!(mode, 0 | 1 | 2 | 6 | 7);
    let frozen_pointer = if pointer_side {
        state
            .xi1_frozen
            .get_mut(&dev_ptr)
            .and_then(|f| f.stored.take())
    } else {
        None
    };
    // NOT_GRABBED (Replay) deactivates a frozen-with-event grab on
    // this device — passive AND explicit (Xorg dix/events.c:1898 calls
    // DeactivateGrab regardless of grab kind). Async/Sync keep the
    // grab until the natural button release. Without the explicit
    // branch a GrabPointer(GrabModeSync) replays the frozen event but
    // stays active → user-visible stuck grab.
    let pointer_has_event = frozen_pointer.is_some();
    if pointer_replay && state.active_pointer_grab.is_some_and(|grab| grab.passive) {
        // Xorg `DeactivatePointerGrab` → `DoEnterLeaveEvents(grab
        // window → sprite, NotifyUngrab)` (dix/events.c:1711): mirror
        // the activation chain emitted in pointer_fanout so the client's
        // crossing state rebalances. The subsequent replay (below)
        // re-delivers the press to the natural target, matching Xorg's
        // ungrab-crossings-then-replayed-press order. Shared with the XI1
        // ReplayThisDevice path.
        deactivate_passive_pointer_grab_crossings(state);
    } else if pointer_replay
        && pointer_has_event
        && state
            .active_pointer_grab
            .is_some_and(|g| g.owner == client_id)
    {
        deactivate_core_pointer_grab(state, backend, client_id);
    }

    let keyboard_side = matches!(mode, 3..=7);
    let frozen_keyboard = if keyboard_side {
        state
            .xi1_frozen
            .get_mut(&dev_kbd)
            .and_then(|f| f.stored.take())
    } else {
        None
    };
    // The activating core key was already delivered to the grab owner. Its
    // parallel XI1 form can be pending from the device enqueue path; Sync
    // must not replay it and consume the allowance intended for the next
    // physical key event.
    if mode == 4
        && let Some(
            crate::server::QueuedInputEvent::HostKey(event)
            | crate::server::QueuedInputEvent::HostKeyTransition(event, _),
        ) = frozen_keyboard.as_ref()
    {
        let press_evcode =
            crate::server::XI_FIRST_EVENT + crate::xinput::XI_DEVICE_KEY_PRESS_OFFSET;
        if let Some(index) = state.sync_pending.iter().position(|pending| {
            pending.device == dev_kbd
                && matches!(&pending.event, crate::server::QueuedInputEvent::Xi1Routed(q)
                    if q.evcode == press_evcode && q.detail == event.keycode && q.time == event.time)
        }) {
            state.sync_pending.remove(index);
        }
    }
    // GH #59: a synchronous passive key grab's activating press is
    // recorded in BOTH the unified activating slot (`Xi1Freeze::stored`,
    // taken above) AND the XI1 pending queue. Xorg's ComputeFreezes replays the stored
    // activating event only for Replay*, never for Sync*
    // (dix/events.c:1320-1370). On SyncKeyboard, drop that duplicate
    // queued XI1 DeviceKeyPress so the closing `xi1_compute_freezes`
    // doesn't replay the grab's own already-delivered press — that
    // replay would trip FreezeNextEvent → FrozenWithEvent, consuming the
    // SyncKeyboard allowance meant for the next *physical* event and
    // withholding the terminating release (sxhkd's dead keyboard).
    if keyboard_replay
        && state
            .active_keyboard_grab
            .is_some_and(|g| g.owner == client_id)
    {
        let is_passive = matches!(
            state.active_keyboard_grab.map(|g| g.source),
            Some(crate::server::ActiveKeyboardGrabSource::PassiveKey { .. })
        );
        let kbd_has_event = frozen_keyboard.is_some()
            || state
                .sync_pending
                .iter()
                .any(|pending| pending.device == dev_kbd);
        if is_passive {
            state.active_keyboard_grab = None;
        } else if kbd_has_event {
            // Explicit GrabKeyboard(GrabModeSync): deactivate on replay
            // too (Xorg NOT_GRABBED → DeactivateGrab), emitting the
            // FocusOut(NotifyUngrab) chain. Else the grab stays stuck.
            deactivate_core_keyboard_grab(state, client_id);
        }
    }

    if pointer_replay
        && let Some(crate::server::QueuedInputEvent::HostPointer(event)) = frozen_pointer
    {
        // Snapshot the xid_map so we can release the immutable
        // borrow on `backend` before pointer_event_fanout_to_state
        // mutates `state`. The map is small (a few hundred entries)
        // and AllowEvents-replay is rare, so the clone is cheap
        // compared to the wire writes the fanout produces.
        let xid_map = backend.xid_map().clone();
        // Deliver core and XI2 device events to the natural target on
        // replay, but do not regenerate XI_RawButtonPress: raw events
        // describe physical input and were delivered before the grab froze.
        // The XI2 freeze-filter at pointer_fanout.rs:309-316 (cinnamon
        // aea9b0f) restricts XI2 press to the grab owner ONLY
        // during sync-passive-grab freeze; the natural target
        // never received XI2 during the freeze. Trace evidence
        // from MATE on silence (2026-05-28): marco activates
        // passive grab on the panel, AllowEvents fires, mate-panel
        // (only XI2 mask, no core mask) saw the queued release
        // but no press → menu clicks dead.
        let _dropped = replay_frozen_pointer_event_to_state(state, backend, &xid_map, event);
    }
    if keyboard_replay
        && let Some(crate::server::QueuedInputEvent::HostKeyTransition(
            event,
            master_transition_accepted,
        )) = frozen_keyboard
    {
        let _dropped = crate::core_loop::key_fanout::replay_frozen_key_to_focus_after_transition(
            state,
            event,
            master_transition_accepted,
        );
    } else if keyboard_replay
        && let Some(crate::server::QueuedInputEvent::HostKey(event)) = frozen_keyboard
    {
        let _dropped = replay_frozen_key_to_focus(state, event);
    }
    // ComputeFreezes: replay the per-device XI1 queues + withheld
    // core keys now that the sync states changed (Xorg has ONE
    // AllowSome for both protocols).
    let xid_map = backend.xid_map().clone();
    crate::core_loop::pointer_fanout::xi1_compute_freezes(state, backend, &xid_map);
    Ok(RequestOutcome::Handled)
}

/// Record a client's XI version the way Xorg `ProcXIQueryVersion` stores
/// it in `XIClientRec`: the first query sets it; a later query raises it
/// only when both the stored and the new version are 2.2 or newer
/// ("Peter promises to never again break backward compatibility").
/// Otherwise the stored version stays — Xorg then answers a lower request
/// with BadValue and a higher one with the stored version; yserver keeps
/// answering with the negotiated version, so only the stored value (what
/// `FilterRawEvents` reads) follows Xorg here.
fn record_xi2_client_version(state: &mut ServerState, client_id: ClientId, version: (u16, u16)) {
    match state.xi2_client_versions.get(&client_id) {
        None => {
            state.xi2_client_versions.insert(client_id, version);
        }
        Some(&stored) => {
            if version >= (2, 2) && stored >= (2, 2) && version > stored {
                state.xi2_client_versions.insert(client_id, version);
            }
        }
    }
}

fn handle_set_input_focus(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some(window) = x11::input_focus_window(body) {
        // Validation per Xorg SetInputFocus (dix/events.c): revert_to
        // ∈ {None, PointerRoot, Parent} else BadValue; a focus window
        // (anything other than None(0)/PointerRoot(1)) must exist
        // (BadWindow) and be viewable (BadMatch).
        let revert_to = header.data;
        if revert_to > 2 {
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_VALUE,
                u32::from(revert_to),
                42,
            );
        }
        if let Some((code, value)) = core_focus_window_error(state, window) {
            return emit_x11_error(state, client_id, sequence, code, value, 42);
        }
        let time = body
            .get(4..8)
            .map_or(0, |b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]));
        apply_core_input_focus(state, client_id, sequence, window, revert_to, time);
    }
    debug!("client {} #{} SetInputFocus", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

/// The window check of Xorg `SetInputFocus`: a focus other than
/// None(0)/PointerRoot(1) must be an existing window (BadWindow) that is
/// viewable (BadMatch). Returns `(error code, errorValue)`.
fn core_focus_window_error(state: &ServerState, window: ResourceId) -> Option<(u8, u32)> {
    if window.0 <= 1 {
        return None;
    }
    match state.resources.window(window) {
        None => Some((x11::error::BAD_WINDOW, window.0)),
        Some(w) if w.map_state != crate::resources::MapState::Viewable => {
            Some((x11::error::BAD_MATCH, window.0))
        }
        Some(_) => None,
    }
}

/// The rest of Xorg `SetInputFocus` for the master keyboard, whose focus
/// is the core focus (core SetInputFocus and XISetFocus on device 3 both
/// land here): the timestamp gate, the FocusOut/FocusIn chain, and the
/// new focus/revert_to/time. `window` has passed
/// [`core_focus_window_error`].
fn apply_core_input_focus(
    state: &mut ServerState,
    client_id: ClientId,
    sequence: SequenceNumber,
    window: ResourceId,
    revert_to: u8,
    time: u32,
) {
    // Xorg SetInputFocus: requests with a time LATER than the
    // current time or EARLIER than the last focus time are
    // silently ignored.
    let now = state
        .timestamp_now()
        .max(state.xi1_last_input_time)
        .max(state.core_focus.time);
    if time != 0
        && (crate::core_loop::xi1_focus::time_after(time, now)
            || crate::core_loop::xi1_focus::time_after(state.core_focus.time, time))
    {
        debug!(
            "client {} #{} SetInputFocus ignored (time {time} outside [{}, {now}])",
            client_id.0, sequence.0, state.core_focus.time
        );
        return;
    }
    debug!(
        "focus decision: client {} SetInputFocus 0x{:x} revert_to={revert_to}",
        client_id.0, window.0
    );
    log::trace!(
        target: "yserver::input::focus",
        "SetInputFocus client={} window={} revert_to={revert_to}",
        state.debug_client_label(client_id),
        state.debug_window_label(window),
    );
    let from_raw = state.core_focus.raw;
    let to_raw = window.0;
    if from_raw != to_raw {
        // Xorg SetInputFocus (dix/events.c:4923): the focus transition
        // is reported NotifyWhileGrabbed (3) while a keyboard grab is
        // active, else NotifyNormal (0). bspwm focuses a newly-mapped
        // window WHILE sxhkd's synchronous passive key grab is still
        // active; emitting NotifyNormal there told GLFW/kitty it had
        // genuinely taken focus mid-grab, and its focus state machine
        // then ignored every typed key (the keys still routed
        // correctly to its window — only the FocusIn mode was wrong).
        // Mirrors the same gate in `revert_core_focus_from`.
        let mode = if state.active_keyboard_grab.is_some() {
            3 // NotifyWhileGrabbed
        } else {
            0 // NotifyNormal
        };
        emit_core_focus_transition(state, from_raw, to_raw, mode);
    }
    state.core_focus = crate::server::CoreFocus {
        raw: to_raw,
        revert_to,
        time: if time == 0 { now } else { time },
    };
    // Legacy mirror — the key fanout's `current_focus` and other
    // readers still consult the per-client field; None/PointerRoot
    // map to ROOT_WINDOW there (the fanout resolves PointerRoot
    // through `state.core_focus` directly).
    let mirror = match to_raw {
        0 | 1 => ROOT_WINDOW,
        w => ResourceId(w),
    };
    for c in state.clients.values_mut() {
        c.focused_window = mirror;
    }
}

/// Focus revert when the focus window (or an ancestor) becomes
/// unviewable or is destroyed — Xorg `DeleteWindowFromAnyEvents`
/// (dix/events.c:5889-5931), reached from both `UnrealizeTree`
/// (unmap) and window deletion. Reverts per `revert_to`: None →
/// None; PointerRoot → PointerRoot; Parent → nearest viewable
/// ancestor, and `revert_to` collapses to RevertToNone.
fn revert_core_focus_from(state: &mut ServerState, win: ResourceId, dying: &[ResourceId]) {
    if state.core_focus.raw != win.0 || win == ROOT_WINDOW {
        return;
    }
    let mode = if state.active_keyboard_grab.is_some() {
        3 // NotifyWhileGrabbed
    } else {
        0 // NotifyNormal
    };
    let (to_raw, new_revert) = match state.core_focus.revert_to {
        2 => {
            // RevertToParent: the nearest surviving viewable ancestor
            // (Xorg's `while (!parent->realized)` walk — `dying`
            // marks windows in a subtree being destroyed, which are
            // still Viewable at this point but won't survive).
            let mut parent = state
                .resources
                .window(win)
                .map_or(ROOT_WINDOW, |w| w.parent);
            loop {
                if parent == ROOT_WINDOW {
                    break;
                }
                let Some(w) = state.resources.window(parent) else {
                    parent = ROOT_WINDOW;
                    break;
                };
                if w.map_state == crate::resources::MapState::Viewable && !dying.contains(&parent) {
                    break;
                }
                if w.parent == parent {
                    break;
                }
                parent = w.parent;
            }
            (parent.0, 0)
        }
        1 => (1, state.core_focus.revert_to),
        _ => (0, state.core_focus.revert_to),
    };
    emit_core_focus_transition(state, win.0, to_raw, mode);
    state.core_focus.raw = to_raw;
    state.core_focus.revert_to = new_revert;
    let mirror = match to_raw {
        0 | 1 => ROOT_WINDOW,
        w => ResourceId(w),
    };
    for c in state.clients.values_mut() {
        c.focused_window = mirror;
    }
}

/// Unmap-side focus revert: fire `revert_core_focus_from` when the
/// focus window stopped being viewable (covers an unmapped ancestor —
/// Xorg unrealizes the whole tree and hits the focus check per child).
fn revert_core_focus_if_unviewable(state: &mut ServerState) {
    let raw = state.core_focus.raw;
    if raw <= 1 {
        return;
    }
    let viewable = state
        .resources
        .window(ResourceId(raw))
        .is_some_and(|w| w.map_state == crate::resources::MapState::Viewable);
    if !viewable {
        revert_core_focus_from(state, ResourceId(raw), &[]);
    }
}

/// Emit the FocusOut/FocusIn chain for a core focus transition
/// (`crate::crossings::focus_transition_events`) through the normal
/// per-window event-mask filter, plus the matching XI2 focus events
/// on the endpoint windows. `mode` is the wire NotifyNormal(0) /
/// NotifyWhileGrabbed(3) / NotifyGrab(1) / NotifyUngrab(2) value.
pub(crate) fn emit_core_focus_transition(
    state: &mut ServerState,
    from_raw: u32,
    to_raw: u32,
    mode: u8,
) {
    log::trace!(
        target: "yserver::input::focus",
        "FOCUS-EMIT from={} to={} mode={mode}",
        state.debug_window_label(ResourceId(from_raw)),
        state.debug_window_label(ResourceId(to_raw)),
    );
    let pointer_win = crate::core_loop::key_fanout::deepest_window_at_pointer(state);
    // Xorg DoFocusEvents (dix/enterleave.c:1557) short-circuits a
    // same-window transition ONLY for non-grab modes:
    //   `if (from == to && mode != NotifyGrab && mode != NotifyUngrab) return;`
    // For NotifyGrab/NotifyUngrab with from == to (the grab window is
    // already the focus), CoreFocusEvents still runs and reaches
    // CoreFocusNonLinear(W, W) — CommonAncestor(W,W) is W's parent, so
    // both the Out/In endpoint events fire on W with NotifyNonlinear
    // (the intermediate walks are empty). focus_transition_events
    // returns nothing for from == to, so synthesize that pair here.
    // (Grab windows are always real windows, so the None/PointerRoot
    // same-window branch is unreachable from our call sites.)
    let events = if from_raw == to_raw && (mode == 1 || mode == 2) && to_raw > 1 {
        vec![
            crate::crossings::FocusEvent {
                window: ResourceId(to_raw),
                focus_in: false,
                detail: crate::crossings::NOTIFY_NONLINEAR,
            },
            crate::crossings::FocusEvent {
                window: ResourceId(to_raw),
                focus_in: true,
                detail: crate::crossings::NOTIFY_NONLINEAR,
            },
        ]
    } else {
        crate::crossings::focus_transition_events(state, from_raw, to_raw, pointer_win)
    };
    let (ptr_x, ptr_y) = state.pointer_root;
    for e in events {
        let _dropped =
            emit_window_event_to_state(state, e.window, FOCUS_CHANGE_MASK, |buf, seq, order| {
                x11::encode_focus_event_with_mode_detail(
                    buf, seq, order, e.focus_in, e.window, mode, e.detail,
                );
            });
    }
    // Xorg DoFocusEvents: the whole core sequence, then the XI2 one
    // (DeviceFocusEvents), which has its own windows.
    for e in crate::crossings::device_focus_transition_events(state, from_raw, to_raw, pointer_win)
    {
        let evtype = if e.focus_in { 9 } else { 10 };
        let _dropped = emit_xi2_focus_event_to_state(
            state,
            e.window,
            evtype,
            XI2_MAJOR_OPCODE,
            mode,
            e.detail,
            ptr_x,
            ptr_y,
        );
    }
}

fn handle_get_image(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    header: RequestHeader,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    debug!("client {} #{} GetImage", client_id.0, sequence.0);
    let Some(req) = x11::get_image_request(header.data, body) else {
        return Ok(RequestOutcome::Handled);
    };
    // Validation per Xorg ProcGetImage: format ∈ {XYPixmap, ZPixmap}
    // → BadValue; drawable must exist → BadDrawable; the rect must
    // lie fully within the drawable (windows additionally must be
    // viewable) → BadMatch.
    if req.format != 1 && req.format != 2 {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_VALUE,
            u32::from(req.format),
            73,
        );
    }
    let rx0 = i32::from(req.x);
    let ry0 = i32::from(req.y);
    let rx1 = rx0 + i32::from(req.width);
    let ry1 = ry0 + i32::from(req.height);
    if let Some(w) = state.resources.window(req.drawable) {
        // Windows: must be viewable; the rect may include the BORDER
        // (xts XGetImage-7 reads (-1,-1)) but not extend past its
        // outside edges; and — ignoring overlaps — the rect must be
        // fully on the screen (XGetImage-15). Both → BadMatch.
        let bw = i32::from(w.border_width);
        let (ww, wh) = (i32::from(w.width), i32::from(w.height));
        let viewable = w.map_state == crate::resources::MapState::Viewable;
        let in_window = rx0 >= -bw && ry0 >= -bw && rx1 <= ww + bw && ry1 <= wh + bw;
        let (abs_x, abs_y) = state.resources.window_absolute_position(req.drawable);
        let (root_w, root_h) = state
            .resources
            .window(crate::resources::ROOT_WINDOW)
            .map_or((i32::MAX, i32::MAX), |r| {
                (i32::from(r.width), i32::from(r.height))
            });
        // The bound is the pixmap the window draws into: the screen, or
        // the backing of the nearest redirected window at or above it,
        // which a window partly off the screen still has whole
        // (`DoGetImage`, `dix/dispatch.c:2176-2210`).
        let (bx, by, bwidth, bheight) = match redirected_ancestor_or_self(state, req.drawable)
            .and_then(|r| state.resources.window(r).map(|w| (r, w)))
        {
            Some((r, rw)) => {
                let (rx, ry) = state.resources.window_absolute_position(r);
                let rbw = i32::from(rw.border_width);
                (
                    rx - rbw,
                    ry - rbw,
                    i32::from(rw.width) + 2 * rbw,
                    i32::from(rw.height) + 2 * rbw,
                )
            }
            None => (0, 0, root_w, root_h),
        };
        let on_screen = abs_x + rx0 >= bx
            && abs_y + ry0 >= by
            && abs_x + rx1 <= bx + bwidth
            && abs_y + ry1 <= by + bheight;
        if !viewable || !in_window || !on_screen {
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_MATCH,
                req.drawable.0,
                73,
            );
        }
    } else if let Some(p) = state.resources.pixmap(req.drawable) {
        if rx0 < 0 || ry0 < 0 || rx1 > i32::from(p.width) || ry1 > i32::from(p.height) {
            return emit_x11_error(
                state,
                client_id,
                sequence,
                x11::error::BAD_MATCH,
                req.drawable.0,
                73,
            );
        }
    } else {
        return emit_x11_error(
            state,
            client_id,
            sequence,
            x11::error::BAD_DRAWABLE,
            req.drawable.0,
            73,
        );
    }
    let byte_order = state
        .clients
        .get(&client_id.0)
        .map_or(yserver_protocol::x11::ClientByteOrder::LittleEndian, |c| {
            c.byte_order
        });
    let host_xid = if req.drawable == ROOT_WINDOW {
        Some(backend.window_id())
    } else {
        state
            .resources
            .host_drawable_target(req.drawable)
            .map(|t| t.host_xid())
    };
    let host_reply = host_xid.and_then(|xid| {
        backend
            .get_image(
                origin,
                xid,
                req.format,
                req.x,
                req.y,
                req.width.max(1),
                req.height.max(1),
                req.plane_mask,
            )
            .ok()
            .flatten()
    });
    let buf: Vec<u8> = if let Some(bytes) = host_reply {
        patch_get_image_reply_header(bytes, byte_order, sequence, crate::resources::ROOT_VISUAL.0)
    } else {
        let mut buf: Vec<u8> = Vec::with_capacity(64);
        x11::write_get_image_reply(
            &mut buf,
            byte_order,
            sequence,
            &req,
            crate::resources::ROOT_VISUAL.0,
        )?;
        buf
    };
    let Some(client) = state.clients.get_mut(&client_id.0) else {
        return Ok(RequestOutcome::Handled);
    };
    let _byte_order = client.byte_order;
    Ok(write_to_client(client, client_id, &buf))
}

fn patch_get_image_reply_header(
    mut bytes: Vec<u8>,
    byte_order: x11::ClientByteOrder,
    sequence: SequenceNumber,
    visual: u32,
) -> Vec<u8> {
    if bytes.len() < 32 {
        return bytes;
    }
    let seq = match byte_order {
        x11::ClientByteOrder::LittleEndian => sequence.0.to_le_bytes(),
        x11::ClientByteOrder::BigEndian => sequence.0.to_be_bytes(),
    };
    let len_words = u32::try_from((bytes.len() - 32) / 4).unwrap_or(u32::MAX);
    let len = match byte_order {
        x11::ClientByteOrder::LittleEndian => len_words.to_le_bytes(),
        x11::ClientByteOrder::BigEndian => len_words.to_be_bytes(),
    };
    let vis = match byte_order {
        x11::ClientByteOrder::LittleEndian => visual.to_le_bytes(),
        x11::ClientByteOrder::BigEndian => visual.to_be_bytes(),
    };
    bytes[2..4].copy_from_slice(&seq);
    bytes[4..8].copy_from_slice(&len);
    bytes[8..12].copy_from_slice(&vis);
    bytes
}

/// Rewrite PolyText8/16 embedded font-change items (len == 255):
/// the wire carries the CLIENT font XID, the backend's font table is
/// keyed by HOST xids. Returns the translated body plus the last
/// font's client id (committed to the GC per X11 §8), or
/// `Err(client_xid)` when an id doesn't resolve (→ BadFont).
fn translate_poly_text_fonts(
    state: &ServerState,
    body: &[u8],
    two_byte: bool,
) -> Result<(Vec<u8>, Option<ResourceId>), u32> {
    let mut out = body.to_vec();
    let mut last: Option<ResourceId> = None;
    let mut off = 12usize;
    while off + 2 <= out.len() {
        let len = out[off];
        if len == 255 {
            if off + 5 > out.len() {
                break;
            }
            let client_xid =
                u32::from_be_bytes([out[off + 1], out[off + 2], out[off + 3], out[off + 4]]);
            let Some(font) = state.resources.font(ResourceId(client_xid)) else {
                return Err(client_xid);
            };
            out[off + 1..off + 5].copy_from_slice(&font.host_xid.as_raw().to_be_bytes());
            last = Some(ResourceId(client_xid));
            off += 5;
        } else {
            let n = usize::from(len);
            off += 2 + if two_byte { 2 * n } else { n };
        }
    }
    Ok((out, last))
}

fn handle_poly_text8(
    state: &mut ServerState,
    backend: &mut dyn Backend,
    origin: Option<OriginContext>,
    client_id: ClientId,
    sequence: SequenceNumber,
    body: &[u8],
) -> io::Result<RequestOutcome> {
    if let Some((drawable_raw, gc_id, text_body)) = x11::poly_text_data(body) {
        let drawable = ResourceId(drawable_raw);
        if let Err((code, bad_value)) = validate_drawable_and_gc(state, drawable, ResourceId(gc_id))
        {
            return emit_x11_error(state, client_id, sequence, code, bad_value, 74);
        }
        let (text_body, last_font) = match translate_poly_text_fonts(state, text_body, false) {
            Ok(pair) => pair,
            Err(bad_font) => {
                return emit_x11_error(
                    state,
                    client_id,
                    sequence,
                    x11::error::BAD_FONT,
                    bad_font,
                    74,
                );
            }
        };
        let draw_state = state.resources.resolve_draw_state(ResourceId(gc_id));
        let target = state.resources.host_drawable_target(drawable);
        if let Some(target) = target {
            let st = draw_state.unwrap_or_default();
            backend.apply_clip_state(origin, &st.clip)?;
            backend.apply_draw_state(origin, &st)?;
            backend.poly_text8(origin, target.host_xid(), st.foreground, &text_body)?;
        }
        if let Some(font) = last_font {
            state.resources.set_gc_font(ResourceId(gc_id), font);
        }
        let _dropped = accumulate_damage_full_to_state(state, drawable);
    }
    debug!("client {} #{} PolyText8", client_id.0, sequence.0);
    Ok(RequestOutcome::Handled)
}

